-- Link's Awakening's Trading Sequence as a path (Paths): the fourteen trades
-- in the order the game has them, from the Yoshi Doll won at the Trendy Game
-- to the Magnifying Lens. Official, numbered, shown as its category (so the
-- category opens as the path), made by user 15. Paths are admin-only.
SELECT 4001, 4, 15, 'official', 'editors', 'public', NOW(), 'Trading Sequence', 'trading-sequence', NULL, 'guide', 0, 1, 0, 1, 1952, '#ffad48', 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM path WHERE id = 4001 OR (container_id = 4 AND slug = 'trading-sequence'));
